import{_ as a,o as n,a as p,b as l}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器数据搬入","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/reg_data_load"},{"text":"unalign_load","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/unalign_load"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/unalign_load.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/unalign_load.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"},{"level":3,"title":"从Tensor起始位置搬入","slug":"从Tensor起始位置搬入","link":"#从Tensor起始位置搬入"},{"level":3,"title":"从指定坐标搬入","slug":"从指定坐标搬入","link":"#从指定坐标搬入"}],"lastUpdated":1793173587000}'),c={name:"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/unalign_load.md"};function e(t,s,o,d,r,i){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>unalign_load</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_data_load.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p><code>unalign_load</code>用于将非32字节对齐的Unified Buffer（UB）数据搬入<a href="../reg_tensor/reg_tensor.html">reg_tensor</a>。对象内部维护一个32字节的非对齐搬入寄存器，提供以下两个操作：</p><ul><li><code>prepare</code>：根据源Tensor起始地址初始化非对齐搬入寄存器。设源起始字节地址为<code>src_start_addr</code>，向低地址方向对齐到32字节边界得到<code>aligned_src_start_addr</code>，将<code>[aligned_src_start_addr, aligned_src_start_addr + 32)</code>的数据缓存到非对齐寄存器。该操作不会生成矢量数据寄存器。</li><li><code>load</code>：结合前置缓存，从指定UB地址搬入一个VL（Vector Length，矢量寄存器字节长度）的数据，支持从Tensor起始位置或指定坐标搬入。</li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">unalign_load</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="nf">unalign_load</span><span class="p">()</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">default</span><span class="p">;</span>

<span class="w">    </span><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">prepare</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src_base</span><span class="p">);</span>

<span class="w">    </span><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">load</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src_tile</span><span class="p">);</span>

<span class="w">    </span><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Coord</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">load</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src_tile</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Coord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">coord</span><span class="p">);</span>
<span class="p">};</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>Tensor</td><td>源Tensor类型，由函数实参自动推导，必须位于UB。</td></tr><tr><td>Coord</td><td>源Tensor坐标类型，由函数实参自动推导，仅用于指定坐标的<code>load</code>重载。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>src_base</td><td>输入</td><td><code>prepare</code>使用的源Tensor，其起始地址必须与本次连续搬入序列中首次<code>load</code>的实际搬入地址相同。</td></tr><tr><td>src_tile</td><td>输入</td><td><code>load</code>使用的源Tensor。不传入<code>coord</code>时，从<code>src_tile.engine().begin().get()</code>搬入。</td></tr><tr><td>coord</td><td>输入</td><td>搬入起始元素在<code>src_tile</code>逻辑布局中的坐标，实际搬入地址为<code>(src_tile.data() + src_tile.layout()(coord)).get()</code>。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><table><thead><tr><th>源Tensor元素类型</th><th>返回的寄存器类型</th></tr></thead><tbody><tr><td><code>int4b_t</code></td><td><code>reg_tensor&lt;int4x2_t&gt;</code>，以打包形式保存4bit数据。</td></tr><tr><td><code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int8_t</code>、<code>uint8_t</code>、<code>hifloat8_t</code>、<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int32_t</code>、<code>uint32_t</code>、<code>float</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int64_t</code></td><td><code>reg_tensor&lt;int64_t&gt;</code>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><ul><li><code>prepare</code>：无。</li><li><code>load</code>：返回包含一个VL数据的<code>reg_tensor</code>，仅初始化其<code>reg</code>成员，不初始化<code>mask</code>成员。后续使用依赖mask的计算或<a href="../reg_data_store/store.html">store</a>前，必须通过<code>with_mask</code>等方式设置有效mask。</li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>起始地址无需32字节对齐，但必须满足元素类型的对齐要求。</li><li>同一连续搬入序列必须复用同一个<code>unalign_load</code>对象，并使用同一元素类型。序列开始前调用一次<code>prepare</code>，其源Tensor起始地址必须与首次<code>load</code>的实际搬入地址相同；后续搬入地址每次递增一个VL。地址不连续时，必须根据新的起始地址重新调用<code>prepare</code>。</li><li>指定<code>coord</code>时，坐标维数必须与Tensor布局匹配，坐标不能越界。</li><li><code>load</code>始终搬入一个VL数据，不根据Tensor形状截断，也不支持通过mask缩短实际读取范围。尾部不足一个VL时，仍须为完整读取及前置缓存访问预留合法UB空间；后续计算可使用mask屏蔽无效元素。</li><li><code>prepare</code>向低地址对齐后的32字节缓存访问范围以及<code>load</code>的实际读取范围，均必须位于有效UB地址空间内。不能仅根据逻辑Tensor大小判断访问安全性。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><h3 id="从Tensor起始位置搬入">从Tensor起始位置搬入<a class="header-anchor" href="#从Tensor起始位置搬入">​</a></h3><p>以下示例假设<code>src</code>和<code>dst</code>位于UB，起始地址按<code>uint8_t</code>对齐，源端已为完整VL读取和前置缓存预留合法空间，目的端至少有一个VL的可写空间。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/vector_ops.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyOneVector</span><span class="p">(</span><span class="n">SrcTensor</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">DstTensor</span><span class="w"> </span><span class="n">dst</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">unalign_load</span><span class="w"> </span><span class="n">loader</span><span class="p">;</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">unalign_store</span><span class="w"> </span><span class="n">storer</span><span class="p">;</span>
<span class="w">    </span><span class="n">loader</span><span class="p">.</span><span class="n">prepare</span><span class="p">(</span><span class="n">src</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">loader</span><span class="p">.</span><span class="n">load</span><span class="p">(</span><span class="n">src</span><span class="p">);</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">get_vf_len</span><span class="p">()</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">uint8_t</span><span class="p">);</span>
<span class="w">    </span><span class="n">storer</span><span class="p">.</span><span class="n">store</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>
<span class="w">    </span><span class="n">storer</span><span class="p">.</span><span class="n">flush</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">count</span><span class="p">));</span>
<span class="p">}</span>
</code></pre></div><h3 id="从指定坐标搬入">从指定坐标搬入<a class="header-anchor" href="#从指定坐标搬入">​</a></h3><p><code>prepare</code>没有坐标参数，因此先复制Tensor视图，并将副本的引擎起始位置设置为本次坐标对应的地址。该操作不修改原Tensor，也不复制UB数据。源Tensor元素类型为<code>uint8_t</code>，实际UB空间必须足以覆盖从<code>offset</code>开始的完整VL读取。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadAtCoordinate</span><span class="p">(</span><span class="n">SrcTensor</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">coord</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">src_tile</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="p">;</span>
<span class="w">    </span><span class="n">src_tile</span><span class="p">.</span><span class="n">engine</span><span class="p">().</span><span class="n">begin</span><span class="p">()</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="p">.</span><span class="n">data</span><span class="p">()</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">src</span><span class="p">.</span><span class="n">layout</span><span class="p">()(</span><span class="n">coord</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">unalign_load</span><span class="w"> </span><span class="n">loader</span><span class="p">;</span>
<span class="w">    </span><span class="n">loader</span><span class="p">.</span><span class="n">prepare</span><span class="p">(</span><span class="n">src_tile</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">loader</span><span class="p">.</span><span class="n">load</span><span class="p">(</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">);</span>
<span class="w">    </span><span class="p">(</span><span class="kt">void</span><span class="p">)</span><span class="n">value</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const w=a(c,[["render",e]]);export{h as __pageData,w as default};
